func NewReservedResourcesValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (ReservedResourcesValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing ReservedResourcesValue Attribute Value",
				"While creating a ReservedResourcesValue value, a missing attribute value was detected. "+
					"A ReservedResourcesValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ReservedResourcesValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid ReservedResourcesValue Attribute Type",
				"While creating a ReservedResourcesValue value, an invalid attribute value was detected. "+
					"A ReservedResourcesValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ReservedResourcesValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("ReservedResourcesValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra ReservedResourcesValue Attribute Value",
				"While creating a ReservedResourcesValue value, an extra attribute value was detected. "+
					"A ReservedResourcesValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra ReservedResourcesValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewReservedResourcesValueUnknown(), diags
	}

	amountAttribute, ok := attributes["amount"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`amount is missing from object`)

		return NewReservedResourcesValueUnknown(), diags
	}

	amountVal, ok := amountAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`amount expected to be basetypes.StringValue, was: %T`, amountAttribute))
	}

	resourceKindAttribute, ok := attributes["resource_kind"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`resource_kind is missing from object`)

		return NewReservedResourcesValueUnknown(), diags
	}

	resourceKindVal, ok := resourceKindAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`resource_kind expected to be basetypes.StringValue, was: %T`, resourceKindAttribute))
	}

	if diags.HasError() {
		return NewReservedResourcesValueUnknown(), diags
	}

	return ReservedResourcesValue{
		Amount:       amountVal,
		ResourceKind: resourceKindVal,
		state:        attr.ValueStateKnown,
	}, diags
}

func NewReservedResourcesValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) ReservedResourcesValue {
	object, diags := NewReservedResourcesValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewReservedResourcesValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t ReservedResourcesType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewReservedResourcesValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewReservedResourcesValueUnknown(), nil
	}

	if in.IsNull() {
		return NewReservedResourcesValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewReservedResourcesValueMust(ReservedResourcesValue{}.AttributeTypes(ctx), attributes), nil
}

